mutations.before:
await tx.query(`delete from ${table} where org_id = $1 and campaign_id in ($2, $3)`, [
  orgId,
  row.slug,
  row.id,
]);

mutations.after:
await tx.query(`delete from ${table} where org_id = $1 and campaign_id in ($2)`, [
  orgId,
  row.id,
]);

mutations.before:
if (row.deleted_at === null) {
  throw new Error(`campaign ${row.id} is not tombstoned; refusing to purge it`);
}
